import json, re, html
from pathlib import Path
S=json.loads(Path('source.json').read_text())
T=json.loads(Path('reference-targets.json').read_text())
A=[]

def plain(x):
    return html.unescape(re.sub(r'<[^>]*>', '', x or ''))

def effect(i,kind,measure,description,before,after,unit,population,transition,replacement,sq,pq):
    assert len(sq)>=12 and sq in plain(S[i]['source_xml']), (i,'source quote',sq)
    assert len(pq)>=12 and pq in plain(A[i]['proposed_xml']), (i,'proposal quote',pq)
    return dict(kind=kind,measure_id=measure,description=description,before=before,after=after,unit=unit,affected_population=population,conditions_and_transition=transition,replacement_or_new_burdens=replacement,source_quote=sq,proposed_quote=pq)

def impact(i,classification,assessment,limits,new,effects):
    A[i]['substantive_impact']=dict(version=1,classification=classification,assessment=assessment,scope_limitations=limits,new_burdens_review=new,effects=effects)

for s in S:
    a={k:s[k] for k in ['code_id','source_id','source_sha256','number']}
    a.update(proposed_xml=s['previous_draft']['proposed_xml'],reason='',review_notes='',status='rewrite_draft')
    A.append(a)

# La portée normative des trois premiers alinéas reste celle du brouillon lu.
